with candidate (n, title, artist, image_url, content, image_license, image_credit, image_page) as (
    values
    (1, 'シャボン玉', 'ジャン・シメオン・シャルダン', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d8/Jean_Sim%C3%A9on_Chardin_-_Soap_Bubbles_-_Google_Art_Project.jpg/960px-Jean_Sim%C3%A9on_Chardin_-_Soap_Bubbles_-_Google_Art_Project.jpg', '18世紀フランスの画家シャルダンが1733〜34年ごろに描いた油彩画で、メトロポリタン美術館が所蔵しています。窓辺から身を乗り出した若者が、ストローでシャボン玉をふくらませる一瞬をとらえています。同じ構図の作品はワシントンのナショナル・ギャラリーとロサンゼルス郡立美術館にもあり、シャルダンは評判のよい構図を自ら描き直しました。すぐに消えるシャボン玉は、人生のはかなさを表すヴァニタスの象徴と読まれてきました。抑えた色と静かな光の中で、ふくらむ玉の薄さに目を向けてみてください。', 'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Jean_Siméon_Chardin_-_Soap_Bubbles_-_Google_Art_Project.jpg')
), fresh as (
    select c.*, row_number() over (order by c.n) as k
    from candidate c
    where not exists (select 1 from public.daily_columns d where d.title = c.title)
), free_day as (
    select day::date as display_date, row_number() over (order by day) as k
    from generate_series(
        (now() at time zone 'Asia/Tokyo')::date,
        (now() at time zone 'Asia/Tokyo')::date + 1
            + (select count(*)::int from public.daily_columns
               where display_date >= (now() at time zone 'Asia/Tokyo')::date),
        interval '1 day') as day
    where not exists (select 1 from public.daily_columns d where d.display_date = day::date)
)
insert into public.daily_columns (title, artist, image_url, content, image_license, image_credit, image_page, display_date)
select f.title, f.artist, f.image_url, f.content, f.image_license, f.image_credit, f.image_page, d.display_date
from fresh f join free_day d using (k)
on conflict (display_date) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('藤田嗣治《夢》、約75年ぶりに公開へ', 'サザビーズ香港で最高額落札の藤田嗣治《夢（ラ・フォンテーヌ頌）》が、軽井沢安東美術館で11月10日から公開される。', '藤田嗣治が1949年に描いた油彩《夢（ラ・フォンテーヌ頌）》が、軽井沢安東美術館で2026年11月10日から一般公開される。戦後に渡米した藤田がニューヨーク滞在期に手がけた、動物を擬人化したシリーズに連なる作品で、1949年にニューヨークの画廊での個展で発表され、1951年のマドリードでの個展に出品された後、長く個人コレクションに秘蔵されていた。2026年9月のサザビーズ香港のオークションで同セール出品作中の最高額で落札され、公の場での公開はおよそ75年ぶりとなる。生誕140周年記念企画「ニューヨークの藤田嗣治」（2027年1月11日まで）の中で、ポーラ美術館所蔵の《ラ・フォンテーヌ頌》などと並べて展示される。', '', '作品・作家', 'https://bijutsutecho.com/magazine/news/exhibition/33285',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('カイ・フランク展、1月に東京オペラシティで', 'フィンランドを代表するデザイナー、カイ・フランクの仕事を250点以上でたどる展覧会が2027年1月に開幕する。', 'フィンランドを代表するデザイナー、カイ・フランク（1911〜1989）の展覧会「カイ・フランク展 時代を超えるフィンランド・デザイン」が、2027年1月16日から3月22日まで東京オペラシティ アートギャラリーで開かれる。フランクはイッタラ・ガラス製作所やアラビア製陶所、ヌータヤルヴィ・ガラス製作所でデザインを手がけ、母校では教育にも力を注いだ。ヘルシンキ建築＆デザイン・ミュージアムのコレクションを中心に、ガラス器や陶磁器、ファブリック、スケッチ、写真、映像など250点以上を展示し、「カルティオ」「キルタ」「ティーマ」などの代表的なシリーズを通して、初期から晩年までの仕事の全貌をたどる。', '', '展覧会', 'https://bijutsutecho.com/magazine/news/exhibition/33278',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('藤井光「WHOSE LIGHT?」、アーティゾン美術館で', '石橋財団コレクションと現代作家が共演する「ジャム・セッション」第7回に藤井光が登場。2027年1月31日まで。', 'アーティゾン美術館で、石橋財団コレクションと現代の作家が共演する「ジャム・セッション」シリーズの第7回「石橋財団コレクション×藤井光 WHOSE LIGHT? —だれのひかりか」が開かれている（2027年1月31日まで）。映像やインスタレーションを通じて芸術と歴史、社会の関係を探ってきた藤井光（1976年生まれ）が、石橋財団コレクション22点と自作を組み合わせ、古代ギリシアから中世、近代、戦後までの歴史をたどる。着想源はプラトン『国家』第7巻の「洞窟の比喩」で、古代アテネの反乱を題材にした《第一の事実》や、「ローマの平和」を扱う新作《服従する者を赦し、驕る者を討て》などが並ぶ。', '', '展覧会', 'https://bijutsutecho.com/magazine/news/report/33243',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('舞妓', 'Maiko', '黒田清輝', 'Kuroda Seiki',
        1893,
        (select slug from public.art_movements where slug = 'yoga-meiji'),
        '東京国立博物館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/75/Kuroda_Maiko.jpg/960px-Kuroda_Maiko.jpg', 'フランス留学から帰国した1893年、黒田清輝が初めて訪れた京都で描いた油彩画で、重要文化財に指定されています。鴨川の見える窓辺に腰かけた舞妓と、そばの小娘が呼応するように配されています。窓辺の明るい光の中に人物を置き、着物の色や肌を明るい色調で描いているのが見どころです。黒田はパリでラファエル・コランに学び、外光を取り入れた明るい画風を日本に持ち帰りました。暗い色調が中心だった明治の洋画に、新しい明るさをもたらした流れの起点の一つといえる作品です。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Kuroda_Maiko.jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('アルジェの女たち', 'The Women of Algiers', 'ウジェーヌ・ドラクロワ', 'Eugène Delacroix',
        1834,
        (select slug from public.art_movements where slug = 'romanticism'),
        'ルーヴル美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/74/Femmes_d%27Alger_dans_leur_appartement%2C_Eug%C3%A8ne_Delacroix_-_Mus%C3%A9e_du_Louvre_Peintures_INV_3824.jpg/960px-Femmes_d%27Alger_dans_leur_appartement%2C_Eug%C3%A8ne_Delacroix_-_Mus%C3%A9e_du_Louvre_Peintures_INV_3824.jpg', '1832年、フランスの外交使節団に加わって北アフリカを訪れたドラクロワは、旅の途中で立ち寄ったアルジェで、女性たちの居室を訪れる機会を得ました。その体験をもとに描き、1834年のサロンに出品したのが本作です。薄暗い室内でくつろぐ女性たちの衣装や調度を、豊かな色彩で描いています。線と輪郭を重んじた新古典主義に対し、色と光で情感を伝えるロマン主義の特徴がよく表れ、後の印象派の画家たちにも刺激を与えました。ピカソは1954〜55年に、この絵をもとに15点の連作を描いています。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Femmes_d''Alger_dans_leur_appartement,_Eugène_Delacroix_-_Musée_du_Louvre_Peintures_INV_3824.jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('子どもの湯浴み', 'The Child''s Bath', 'メアリー・カサット', 'Mary Cassatt',
        1893,
        (select slug from public.art_movements where slug = 'impressionism'),
        'シカゴ美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f5/The_Child%27s_Bath_by_Mary_Cassatt_1893.jpg/960px-The_Child%27s_Bath_by_Mary_Cassatt_1893.jpg', 'アメリカ出身でパリを拠点にした画家メアリー・カサットが1893年に描いた油彩画です。女性が膝の上に幼い子を抱き、洗面器で足を洗ってやる日常の一場面を、上から見下ろす視点でとらえています。カサットは1890年にパリで見た日本の浮世絵版画に強い印象を受けており、大胆に切り取った構図、はっきりした輪郭、平面的な模様の扱いにその影響が表れています。印象派の仲間ドガにも学びつつ、光の表現より形と構図に重心を移した作品です。1910年にシカゴ美術館が購入し、同館に入った最初のカサット作品となりました。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:The_Child''s_Bath_by_Mary_Cassatt_1893.jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('下村観山', 'Shimomura Kanzan', '観山',
        1873, 1930, 'japan', array['nihonga']::text[],
        '日本美術院の創設に加わり、横山大観、菱田春草とともに明治・大正の日本画を担った画家。', '1873年、紀州藩に仕えた能楽師の家に生まれ、8歳で一家とともに東京へ移りました。狩野芳崖に師事し、芳崖の紹介で橋本雅邦に学んだのち、1889年に東京美術学校の第一期生として入学しました。

卒業後は同校で教え、1898年には岡倉天心に従って横山大観、菱田春草らとともに日本美術院の創設に参加しました。1903年には文部省の留学生としてイギリスに渡り、1906年には天心とともに茨城県の五浦に移って制作に励みました。

代表作に、第1回文展に出した「木の間の秋」（1907年）、「大原御幸」（1908年）、重要文化財の「弱法師」（1915年）などがあります。1917年には帝室技芸員となり、1930年に横浜で亡くなりました。', 'https://ja.wikipedia.org/wiki/%E4%B8%8B%E6%9D%91%E8%A6%B3%E5%B1%B1')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('テオドール・ジェリコー', 'Théodore Géricault', 'ジェリコー',
        1791, 1824, 'west', array['romanticism']::text[],
        '「メデューズ号の筏」で知られ、ロマン主義絵画の先駆けとなったフランスの画家。', '1791年、フランスのルーアンに生まれました。1808年にカルル・ヴェルネに、1810年からはピエール＝ナルシス・ゲランに師事し、1812年のサロンに出した「突撃する近衛猟騎兵士官」で金賞を得ました。1816年から翌年にかけてイタリアに滞在し、ミケランジェロの力強い人体表現に影響を受けました。

1819年のサロンに出した「メデューズ号の筏」は、実際に起きた難破事件を巨大な画面に描き、賛否両論を巻き起こしました。1820年から1822年にはイギリスに滞在して「エプソムの競馬」を描き、晩年にはサルペトリエール病院の人々をモデルにした「狂人の肖像」の連作を手がけました。

1824年、32歳の若さでパリで亡くなりました。劇的な主題と激しい感情の表現は、筏の漂流者のモデルも務めたドラクロワらに受け継がれ、ロマン主義絵画の先駆けとされています。', 'https://ja.wikipedia.org/wiki/%E3%83%86%E3%82%AA%E3%83%89%E3%83%BC%E3%83%AB%E3%83%BB%E3%82%B8%E3%82%A7%E3%83%AA%E3%82%B3%E3%83%BC')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('ジャン・オノレ・フラゴナール', 'Jean-Honoré Fragonard', 'フラゴナール',
        1732, 1806, 'west', array['rococo']::text[],
        '軽やかな筆で恋や遊びの情景を描き、フランス・ロココの最後を飾った画家。', '1732年、南フランスのグラースに生まれ、6歳のころ家族とパリへ移りました。シャルダンとブーシェに短期間学び、20歳で王立絵画彫刻アカデミーのローマ賞を得て、1756年からおよそ5年間ローマに滞在しました。

1765年には歴史画「カリロエを救うために自らを犠牲にするコレソス」をサロンに出し、批評家ディドロに高く評価されました。その後は貴族や富裕な愛好家のために、恋や遊びの情景をすばやく軽やかな筆づかいで描き、「ぶらんこ」（1767年頃）や「読書する娘」などの代表作を残しました。

1789年のフランス革命の後、ロココの趣味は時代に合わなくなりました。フラゴナールは美術管理委員会の委員としてルーヴルの収蔵品管理に携わりましたが、晩年は不遇のうちに過ごし、1806年にパリで亡くなりました。フランス・ロココを代表し、その時代の最後を飾った画家とされています。', 'https://ja.wikipedia.org/wiki/%E3%82%B8%E3%83%A3%E3%83%B3%E3%83%BB%E3%82%AA%E3%83%8E%E3%83%AC%E3%83%BB%E3%83%95%E3%83%A9%E3%82%B4%E3%83%8A%E3%83%BC%E3%83%AB')
